precision mediump float;
varying vec2 vUv;
uniform float uTime;
uniform vec3 uCol;
uniform vec2 uRes;
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float noise(vec2 p){
  vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);
  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);
}
float fbm(vec2 p){float v=0.0,a=0.5;for(int i=0;i<5;i++){v+=a*noise(p);p*=2.0;a*=0.5;}return v;}
void main(){
  vec2 uv=vUv;
  float ar=uRes.x/uRes.y;
  // 3레이어 FBM — 각기 다른 방향·속도로 흐름
  float f1=fbm(vec2(uv.x*ar*3.0+uTime*0.06,uv.y*3.0+uTime*0.02));
  float f2=fbm(vec2(uv.x*ar*2.0-uTime*0.04,uv.y*2.0+sin(uTime*0.1)*0.3));
  float f3=fbm(vec2(uv.x*ar*5.0+uTime*0.08,uv.y*4.0-uTime*0.03));
  float fog=f1*0.5+f2*0.35+f3*0.15;
  fog=smoothstep(0.15,0.85,fog);
  // 플레이어 중심(화면 중앙) 투명 처리
  float d=length((uv-vec2(0.5))*vec2(ar,1.0));
  fog*=smoothstep(0.12,0.45,d);
  float alpha=fog*0.82;
  gl_FragColor=vec4(uCol*fog*0.8,alpha);
}
